// 临时验证文件：提交前删除。它直接改真实配置文件并恢复，验证端到端路径解析。

func withConfig(t *testing.T, content string, present bool) {
	t.Helper()
	backup, existed := []byte(nil), false
	if b, err := os.ReadFile(thresholdConfigPath); err == nil {
		backup, existed = b, true
	}
	t.Cleanup(func() {
		if existed {
			_ = os.WriteFile(thresholdConfigPath, backup, 0o644)
		} else {
			_ = os.Remove(thresholdConfigPath)
		}
	})
	if present {
		if err := os.MkdirAll(filepath.Dir(thresholdConfigPath), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(thresholdConfigPath, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	} else {
		_ = os.Remove(thresholdConfigPath)
	}
}

func TestVerifyConfigPathIsRepoConfig(t *testing.T) {
	if filepath.Base(thresholdConfigPath) != "thresholds.json" {
		t.Fatalf("config path = %q", thresholdConfigPath)
	}
	if filepath.Base(filepath.Dir(thresholdConfigPath)) != "config" {
		t.Fatalf("config dir = %q", thresholdConfigPath)
	}
}

func TestVerifyConfiguredAndFallback(t *testing.T) {
	withConfig(t, `{"shanghai": 7}`, true)
	if got := LowStockThreshold("shanghai"); got != 7 {
		t.Fatalf("configured = %d, want 7", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("unconfigured = %d, want %d", got, DefaultLowStockThreshold)
	}
}

func TestVerifyFallbackOnMissing(t *testing.T) {
	withConfig(t, "", false)
	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("missing file = %d, want %d", got, DefaultLowStockThreshold)
	}
}

func TestVerifyFallbackOnNonObject(t *testing.T) {
	for _, content := range []string{`[]`, `"nope"`, `not json`, `null`, `[1,2]`} {
		withConfig(t, content, true)
		if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
			t.Fatalf("non-object %q = %d, want %d", content, got, DefaultLowStockThreshold)
		}
	}
}

func TestVerifyFallbackOnBadValue(t *testing.T) {
	withConfig(t, `{"shanghai": "high"}`, true)
	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("bad value = %d, want %d", got, DefaultLowStockThreshold)
	}
}

func TestVerifyFallbackOnUnreadable(t *testing.T) {
	withConfig(t, "", false)
	if err := os.MkdirAll(thresholdConfigPath, 0o755); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(thresholdConfigPath) })
	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
