import (
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdConfigPath 是阈值配置文件，位于仓库根的 config/thresholds.json。
//
// 用源码位置解析而不是进程工作目录，这样不管从哪个目录跑测试/服务，读的都是同一份配置。
var thresholdConfigPath = filepath.Join(configDir(), "thresholds.json")

// configDir 返回仓库根的 config/ 目录。
func configDir() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		return "config"
	}
	return filepath.Join(filepath.Dir(file), "..", "config")
}

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 仓库在 config/thresholds.json 里配了就用自己的阈值；没配、或文件不存在/读不出来/
// 内容不是 JSON 对象时，一律回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, err := readThresholds(thresholdConfigPath)
	if err != nil {
		return DefaultLowStockThreshold
	}
	threshold, ok := thresholds[warehouse]
	if !ok {
		return DefaultLowStockThreshold
	}
	return threshold
}

// readThresholds 读取并解析阈值配置文件；任何错误都由调用方回退到默认值。
func readThresholds(path string) (map[string]int, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, err
	}
	return thresholds, nil
}

